/* ==========================================================================
   Heal phone kit: components as HTML-string builders.
   ICONS, WORDMARK and KIT_STAMP are prepended by update_kit.py (from the app repo).
   Sizes: react-native-size-matters on a Pixel 8 window (411.43 x 914.29 dp), guideline 350 x 680.
   Navigation in prototypes: put data-go="<screen id>" on anything tappable (see go()).
   ========================================================================== */
const DEV={name:'Pixel 8',w:411.43,h:914.29,frame:9};
const KS=DEV.w/350, KMS=1+(KS-1)/2;
const ms=(n)=>n*KMS;                                   /* moderateScale(n, 0.5) */
const PX=(n)=>`${Math.round(n*100)/100}px`;

/* <Icon size={n}> renders at moderateScale(n). Names: see ICONS keys. */
function ic(name,size,color,extra){
  const d=ICONS[name]; if(!d) throw new Error('Unknown icon: '+name);
  const z=PX(ms(size));
  return `<svg width="${z}" height="${z}" viewBox="${d[0]}" fill="none" aria-hidden="true" style="color:${color||'currentColor'};flex:none;${extra||''}">${d[1]}</svg>`;
}
/* Unscaled icon, for anything outside the phone (e.g. a web panel mockup) */
function rawIc(name,size){const d=ICONS[name];return `<svg width="${size}" height="${size}" viewBox="${d[0]}" fill="none" aria-hidden="true">${d[1]}</svg>`}

const go=(id)=>`data-go="${id}"`;
const btn=(label,variant,target,extra)=>`<button type="button" class="btn ${variant}" ${target?go(target):''} ${extra||''}>${label}</button>`;
const sp=(t)=>`<div style="height:var(--${t})"></div>`;   /* <Spacer size={t}/> */
const overlay=(base,top)=>base+top;                      /* screen + drawer/modal on top */

/* HealMark.tsx (30), NiaLogo.tsx (90 wide, 84:27), NiaMascot sm (28; drawn without the small hands) */
function healMark(){const z=PX(ms(30));return `<svg width="${z}" height="${z}" viewBox="0 0 30 30" aria-label="Heal" style="flex:none"><rect width="30" height="30" rx="5.04" fill="#fff"/><path d="M18.9752 5.54471C19.1223 5.26889 19.3706 5.07581 19.7199 4.96548C20.0693 4.85515 20.5106 4.79999 21.0439 4.79999C21.5771 4.79999 22.0001 4.84596 22.3127 4.9379C22.6253 5.02984 22.8643 5.14017 23.0298 5.26889C23.1953 5.3976 23.324 5.58148 23.416 5.82053C23.5079 6.13313 23.5539 6.61122 23.5539 7.25481V22.5629C23.5539 22.9859 23.5355 23.3077 23.4987 23.5283C23.4803 23.7306 23.3976 23.9696 23.2505 24.2455C22.993 24.7419 22.2759 24.9902 21.0991 24.9902C19.8119 24.9902 19.058 24.65 18.8373 23.9696C18.727 23.657 18.6718 23.1789 18.6718 22.5354V16.9362V12.8816H11.3625V22.5629C11.3625 22.9859 11.3441 23.3077 11.3074 23.5283C11.289 23.7306 11.2062 23.9696 11.0591 24.2455C10.8017 24.7419 10.0845 24.9902 8.9077 24.9902C7.62053 24.9902 6.86662 24.65 6.64596 23.9696C6.53563 23.657 6.48047 23.1789 6.48047 22.5354V7.22722C6.48047 6.8043 6.48966 6.4917 6.50805 6.28943C6.54483 6.06877 6.63677 5.82053 6.78387 5.54471C7.04131 5.04823 7.75845 4.79999 8.93529 4.79999C10.2225 4.79999 10.9856 5.14017 11.2246 5.82053C11.3166 6.13313 11.3625 6.61122 11.3625 7.25481V12.8816H18.6718V7.22722C18.6718 6.8043 18.681 6.4917 18.6994 6.28943C18.7362 6.06877 18.8281 5.82053 18.9752 5.54471Z" fill="#BA2747"/><path d="M11.8505 16.0028L11.8806 15.8183C12.1265 14.3087 13.4305 13.2 14.96 13.2H17.5518C17.7992 13.2 17.9998 13.4006 17.9998 13.648C17.9998 15.2562 16.696 16.56 15.0878 16.56H12.3243C12.0284 16.56 11.803 16.2949 11.8505 16.0028Z" fill="#BA2747"/></svg>`}
const SIMI_FACE=`<rect x="0.17627" width="26" height="26" rx="13" fill="#BA2747"/><path d="M1.83613 10.9855C2.14809 7.52853 5.20277 4.05306 8.32105 2.83185" stroke="white" stroke-opacity=".67" stroke-width=".693" stroke-linecap="round"/><path d="M24.4255 15.5046C24.4072 18.1912 22.572 20.4322 20.5705 21.632" stroke="white" stroke-opacity=".67" stroke-width=".693" stroke-linecap="round" opacity=".88"/><rect x="15.4412" y="8.08008" width="6.03876" height="8.499" rx="3.01938" fill="white"/><rect x="16.772" y="9.65479" width="3.57853" height="5.36779" rx="1.78926" fill="black"/><path d="M18.459 11.4406C18.459 11.4406 18.4753 12.3894 17.5913 12.5898C18.4115 12.8088 18.5222 13.6843 18.5222 13.6843C18.5222 13.6843 18.6247 12.8259 19.4115 12.5506C18.5509 12.4676 18.459 11.4406 18.459 11.4406Z" fill="white"/><circle cx="19.755" cy="10.457" r=".675" fill="white"/><rect x="4.9292" y="8.00891" width="6.03876" height="8.499" rx="3.01938" fill="white"/><rect x="6.25854" y="9.80713" width="3.57853" height="5.36779" rx="1.78926" fill="black"/><circle cx="6.869" cy="10.521" r=".675" fill="white"/><path d="M7.94728 11.3695C7.94728 11.3695 7.96353 12.3182 7.07958 12.5186C7.89974 12.7377 8.01047 13.6131 8.01047 13.6131C8.01047 13.6131 8.11293 12.7547 8.89974 12.4794C8.03922 12.3964 7.94728 11.3695 7.94728 11.3695Z" fill="white"/>`;
function niaLogo(w){const W=ms(w||90),H=W*27/84;return `<svg width="${PX(W)}" height="${PX(H)}" viewBox="0 0 84 27" aria-label="Simi" style="display:block">${SIMI_FACE}<text x="36" y="20" fill="#BA2747" font-size="19" font-weight="700" font-family="Instrument Sans, Arial, sans-serif">Simi</text></svg>`}
function mascot(size){const z=PX(ms(size||28));return `<svg width="${z}" height="${z}" viewBox="0 0 26.2 26" aria-hidden="true" style="flex:none">${SIMI_FACE}</svg>`}

/* ---------- system chrome and layout ---------- */
const sbar=()=>`<div class="sbar"><span>9:41</span><i><svg width="16" height="12" viewBox="0 0 16 12" aria-hidden="true"><path d="M8 11.5 0.3 3.4C2.4 1.5 5.1.4 8 .4s5.6 1.1 7.7 3L8 11.5Z" fill="#1D1D1B"/></svg><svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><path d="M13.5 13.5V.5L.5 13.5h13Z" fill="#1D1D1B"/></svg><svg width="9" height="15" viewBox="0 0 9 15" aria-hidden="true"><rect x="2.5" y="0" width="4" height="2" rx=".6" fill="#1D1D1B"/><rect x=".75" y="1.75" width="7.5" height="12.5" rx="1.6" fill="none" stroke="#1D1D1B" stroke-width="1.3"/><rect x="2" y="4.5" width="5" height="8.5" rx=".8" fill="#1D1D1B"/></svg></i></div>`;
const gbar=()=>`<div class="gbar"></div>`;
/* A full screen: status bar, your content, gesture bar. `after` is drawn on top (drawer, modal). */
const screen=(inner,after)=>`<div class="scr">${sbar()}${inner}${gbar()}</div>${after||''}`;
const menuBtn=(target)=>`<button type="button" class="menubtn" aria-label="Open menu" ${target?go(target):''}>${ic('menu',22)}</button>`;
const appBar=(target)=>`<div class="row between" style="padding:var(--sm) 0">${menuBtn(target)}${healMark()}</div>`;
const shdr=(title,target)=>`<div class="shdr"><button type="button" class="iconbtn" aria-label="Back" ${go(target||'@back')}>${ic('chevron-left',24)}</button><span class="t t-h3">${title}</span><span style="width:${PX(ms(24))}"></span></div>`;
/* LogoutConfirmModal: title, optional message, buttons on the right (pass btn(...,'outline sm') etc.) */
const confirmModal=(title,msg,buttons)=>`<div class="modal"><div class="mcard new"><p class="t-body">${title}</p>${msg?`${sp('xs')}<p class="t-bs c2">${msg}</p>`:''}<div class="mbtns">${buttons}</div></div></div>`;
/* AppUpdateModal: badge in two rings, title, muted message, one big button; not dismissable */
const bigModal=(badgeIcon,title,msg,button)=>`<div class="modal"><div class="mcard big new"><div class="badge"><span>${badgeIcon}</span></div>${sp('md')}<p class="t-h3 center">${title}</p>${sp('sm')}<p class="t-body cm center">${msg}</p>${sp('lg')}${button}</div></div>`;

/* ---------- Profile ---------- */
function mrow(icon,label,o){o=o||{};
  return `<button type="button" class="mrow${o.red?' red':''}${o.isNew?' new':''}" ${o.go?go(o.go):''}><span class="l">${icon}<span>${label}</span></span><span class="r">${o.value?`<span class="v">${o.value}</span>`:''}<span class="chev flip">${ic('chevron-left',14,'#1D1D1B')}</span></span></button>`}
/* The rows ProfileScreen shows today (Nutrition Goals, Notifications and Log Out are hidden in the code) */
const PROFILE_ROWS=()=>[mrow(ic('p-person',18),'Personal Information'),mrow(ic('p-program',18),'My Program',{value:'42 days'}),mrow(ic('p-privacy',18),'Privacy Policy'),mrow(ic('p-terms',18),'Terms and Conditions')];
function profileScreen(o){o=o||{};
  return screen(`<div class="scroll pad">${appBar(o.menu)}
    <div class="p-hero"><div class="p-outline"><div class="p-avatar">${ic('person',46,'#fff')}<span class="p-badge">${ic('pencil',12,'#fff')}</span></div></div>
      <div class="p-meta"><span class="p-name">Testing User</span><span class="p-prog">Diwali Glow</span><span class="p-day">Day 10 of 42 &bull; Lose fat</span></div></div>
    <div class="p-tiles"><div class="p-tile"><small>Weight</small><b>115 kgs</b></div><div class="p-tile"><small>Height</small><b>160 cm</b></div><div class="p-tile"><small>Age</small><b>26 yrs</b></div></div>
    <div style="padding-bottom:${PX(ms(20))}">${(o.rows||PROFILE_ROWS()).join('')}</div></div>`,o.after)}

/* ---------- Onboarding: OnboardingConversationHeader + WizardScreenLayout ---------- */
/* o: {prev, hair (percent), count, eyebrow, title, body, foot, footNew, after} */
function ob(o){
  const head=`${o.hair?`<div class="hair"><i style="width:${o.hair}%"></i></div>`:''}<div class="backrow"><span class="prev t-cap" style="opacity:${o.prev?1:0}">Prev ${ic('chevron-left',14,'var(--link)','transform:rotate(90deg)')}</span>${o.count?`<span class="count t-cap c2">${o.count}</span>`:''}</div>`;
  const logo=o.hair?`<div class="pad">${niaLogo(90)}${sp('sm')}</div>`:`<div class="pad">${sp('xxxl')}${niaLogo(90)}${sp('md')}</div>`;
  return screen(`${head}${logo}<div class="scroll pad" style="padding-bottom:var(--xl)">${o.eyebrow?`<p class="t-bs c2">${o.eyebrow}</p>${sp('xs')}`:''}<p class="t-h3 cs">${o.title}</p>${sp('lg')}${o.body||''}</div><div class="ob-foot${o.footNew?' new':''}">${o.foot}</div>`,o.after)}
const LEGAL=`<p class="t-cap cm center">By signing in, you agree to the <span class="cl">Terms and Conditions</span> and <span class="cl">Privacy Policy</span></p>${sp('md')}`;
const signInScreen=(next)=>ob({eyebrow:'Sign in to Heal by Nurrish',title:'Enter your email',body:`<div class="field">testing.user@mail.com</div>`,foot:`${LEGAL}${btn('Continue','primary',next)}`});
const otpScreen=(next,after)=>ob({prev:true,eyebrow:'Check your email',title:'Enter OTP',after,
  body:`<p class="t-body c2">testing.user@mail.com</p>${sp('lg')}<div class="otp"><span>4</span><span>8</span><span>2</span><span>9</span></div>${sp('md')}<div class="row between"><span class="t-cap c2">Didn't receive OTP?</span><span class="t-cap cd">Resend in 24s</span></div>`,
  foot:`${LEGAL}${btn('Verify','primary',next)}`});

