/* ---------- Drawer (DrawerNavigator) ---------- */
function drawerItem(icon,label,o){o=o||{};
  return `<button type="button" class="ditem${o.on?' on':''}${o.locked?' locked':''}" ${o.go?go(o.go):''}>${icon}<span>${label}</span>${o.locked?`<span class="lk">${ic('lock',16,'var(--dis)')}</span>`:''}</button>`}
/* The items the menu shows today, in order. `active` = label of the current screen. */
const DRAWER_ITEMS=(active)=>[['chat','Chat'],['diet','View diet plan'],['workout','View workout plan'],['analytics','Analytics'],['profile','Profile'],['bell','Preferences']].map(([i,l])=>drawerItem(ic(i,22),l,{on:l===active}));
function drawer(items,o){o=o||{};
  return `<div class="scrim" ${o.close?go(o.close):''}></div><div class="drawer"><div class="dbrand"><span style="display:block;width:${PX(ms(99))}">${WORDMARK}</span><button type="button" class="iconbtn" aria-label="Close menu" ${o.close?go(o.close):''}>${ic('close',28)}</button></div>
    ${(items||DRAWER_ITEMS('Chat')).join('')}<button type="button" class="ditem logout">${ic('p-logout',22)}<span>Logout</span></button><p class="t-cap cd dver">${KIT_STAMP.appVersion||''}</p></div>`}

/* ---------- Analytics: calories card with MacroBreakdown ---------- */
/* m: grams {protein, carbs, fat, fibre}; slices are each macro's share of calories (4/4/9 kcal per gram) */
function macroBreakdown(m){
  const C={protein:'var(--c-success)',carbs:'var(--c-warning)',fat:'var(--c-fatAccent)',fibre:'var(--c-fiberAccent)'};
  const size=ms(92), stroke=ms(14), r=(size-stroke)/2, len=2*Math.PI*r, gap=ms(2), c=size/2;
  const kcal={protein:m.protein*4,carbs:m.carbs*4,fat:m.fat*9}, total=kcal.protein+kcal.carbs+kcal.fat;
  let used=0;
  const ring=total<=0?`<circle cx="${c}" cy="${c}" r="${r}" stroke="var(--c-analyticsDonutTrack)" stroke-width="${stroke}" fill="none"/>`:
    ['protein','carbs','fat'].map(k=>{const L=kcal[k]/total*len, off=used; used+=L; if(L<1) return '';
      return `<circle cx="${c}" cy="${c}" r="${r}" stroke="${C[k]}" stroke-width="${stroke}" fill="none" stroke-dasharray="${Math.max(.5,L-gap)} ${len-L+gap}" stroke-dashoffset="${-off}" transform="rotate(-90 ${c} ${c})"/>`}).join('');
  const g=(n)=>`${Number(n.toFixed(1)).toLocaleString()} g`;
  const item=(k,l)=>`<div class="mac-item"><span class="mac-lbl"><span class="mac-dot" style="background:${C[k]}"></span><span class="t-bs">${l}</span></span><span class="t-body mac-g">${g(m[k])}</span></div>`;
  return `<div class="mac"><div class="mac-row" style="margin-bottom:calc(-1*var(--xs))"><span class="mac-spacer"></span><span class="mac-side t-cap cd">Macros</span></div>
    <div class="mac-row"><svg width="${PX(size)}" height="${PX(size)}" viewBox="0 0 ${size} ${size}" style="flex:none" aria-label="Calories by macro">${ring}</svg><div class="mac-side mac-rows">${item('protein','Protein')}${item('carbs','Carbs')}${item('fat','Fat')}</div></div>
    <div class="mac-row"><span class="mac-spacer"></span><div class="mac-side mac-fibre"><p class="t-cap cd" style="margin-bottom:var(--xs)">Others</p>${item('fibre','Fibre')}</div></div></div>`;
}
/* o: {eaten, target, macros, burned, extra (HTML before "View my daily log"), menu, after} */
function analyticsDay(o){o=o||{};
  const eaten=o.eaten??1240, target=o.target??2246, burned=o.burned??320, f=(n)=>n.toLocaleString();
  return screen(`<div class="scroll"><div class="pad">${appBar(o.menu)}</div>
    <div class="pad row between" style="padding-bottom:var(--sm)">${ic('chevron-left',24,'var(--tx)')}<span class="t-h3">Today</span><span class="flip" style="display:grid;opacity:.3">${ic('chevron-left',24,'var(--tx)')}</span></div>
    <div class="pad" style="padding-bottom:var(--xl)"><div class="card" style="margin-top:var(--lg)">
      <p class="t-over c2" style="text-transform:uppercase">Today's calories</p>
      <div style="margin-top:var(--lg)"><p class="t-cap c2">Eaten</p>
        <div style="display:flex;flex-wrap:wrap;align-items:baseline;column-gap:var(--xs);row-gap:var(--xxs);margin-top:var(--xs)"><span class="t-display cp">${f(eaten)}</span><span class="t-bs c2">of ${f(target)} kcal</span><span class="t-cap semi" style="margin-left:auto">${f(Math.max(0,target-eaten))} left</span></div>
        ${o.macros===null?'':macroBreakdown(o.macros||{protein:62,carbs:150,fat:40,fibre:18})}</div>
      <div class="hr" style="margin:var(--lg) 0"></div>
      <p class="t-cap c2">Active Burned</p>
      <div class="row" style="gap:var(--xs);align-items:baseline;margin-top:var(--xs)"><span class="t-display" style="color:var(--violet)">${f(burned)}</span><span class="t-cap cd">kcal</span></div>
      ${o.extra||''}
      <div class="hr" style="margin-top:var(--lg)"></div>
      <button type="button" class="loglink"><span class="t-bs semi">View my daily log</span><span class="flip" style="display:grid">${ic('chevron-left',16,'var(--p)')}</span></button>
    </div></div></div>`,o.after)}

