/* ---------- Mounting a phone on a page ---------- */
/* mountPhone(box, html, {maxHeight}): draws the Pixel 8 at real size inside `box` and scales it to fit. */
function mountPhone(box,html,opt){
  box.classList.add('devbox');
  box.innerHTML=`<div class="device"><div class="devscreen"><div class="punch"></div>${html}</div></div>`;
  fitPhone(box,opt); return box;
}
function fitPhone(box,opt){opt=opt||{};
  const dev=box.querySelector('.device'); if(!dev) return 1;
  const fw=DEV.w+2*DEV.frame, fh=DEV.h+2*DEV.frame;
  let k=box.clientWidth/fw; if(opt.maxHeight) k=Math.min(k,opt.maxHeight/fh);
  k=Math.max(.3,Math.min(1,k));
  dev.style.transform=`scale(${k})`; dev.style.left=PX(Math.max(0,(box.clientWidth-fw*k)/2)); box.style.height=PX(fh*k);
  return k;
}
